package com.cpf.batch.worker; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/internal/v1/worker") public class WorkerControlController { private final WorkerRuntime r;public WorkerControlController(WorkerRuntime r){this.r=r;} @PostMapping("/drain") ResponseEntity<Void> drain(){r.drain();return ResponseEntity.accepted().build();} @PostMapping("/resume") ResponseEntity<Void> resume(){r.resume();return ResponseEntity.accepted().build();} }